def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def P(n,winter=False):return I('pears',n,'','small firm winter cooking pears, about 120 g each' if winter else 'medium firm pears, about 170 g each','Use firm pears of similar size; dessert pears soften sooner than hard winter cooking varieties. Check tenderness rather than relying only on time.')
def W(n,k='water'):return I(k,n,'ml','drinking water','Use the same volume of unsweetened pear juice in a fruit dish for a sweeter flavor.')
def S(n,k='sugar'):return I(k,n,'g','granulated sugar','Reduce for a less sweet result; this is not a shelf-stable preserve.')
def B(n,k='butter'):return I(k,n,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def Z(n):return I('zest',n,'g','thin strips of lemon zest, yellow part only','Use the same weight of orange zest; remove strips before serving.')
def L(n):return I('lemon',n,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
def C(n=1):return I('cinnamon',n,'','small cinnamon stick','Use 0.25 tsp ground cinnamon per stick; leave ground spice in the sauce.')
def clove(n):return I('cloves',n,'','whole cloves','Omit for a milder dish, or use 0.1 g ground cloves per whole clove and leave in the sauce.')
def wine(n,port=False):return I('wine',n,'ml','ruby port' if port else 'dry red wine','Use the same volume of unsweetened red grape juice for an alcohol-free but sweeter variation.')
def cream(n):return I('cream',n,'ml','heavy cream','Use the same volume of a plant-based cream suited to the stated use.')
def milk(n):return I('milk',n,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor and texture differ.')
def yolk(n):return I('yolks',n,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; an egg-free version needs a different thickening method.')
def add(n,title,y,minutes,desc,items,steps,notes,category='Desserts',refs=()):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=y,yieldUnit='servings',minutes=minutes,totalMinutes=minutes,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T17:00:00Z',notes=notes+' Missing amounts, oven settings, yields and timings are explicit modern adaptation estimates, not exact historical conversions. Not kitchen-tested. Scaling changes quantities, not cooking time or temperature. Refrigerate in shallow containers within 2 hours at 4°C (40°F) or colder; this is not a canning recipe.',source=s['recipe']['source']+' SavorShelf measured adaptation.'+''.join(' Reference: '+x for x in refs));r.pop('variants',None);r['sourceAliases']=[rows[o]['id'] for o,d in merges.items() if d==n]
