 items=[P(fruit,winter),W(wat)]+([S(sug)] if sug else [])+list(extras)
 prep='Rinse {{pears}}. '+('Leave the skins on. ' if skin else 'Peel them. ')+('Scoop out the cores and seeds from the base with a melon baller, keeping the pears whole.' if whole else 'Halve lengthwise and scoop out all cores and seeds.')
 season=', '.join('{{'+i['key']+'}}' for i in extras)
 steps=[prep,'Put {{water}}'+(' and {{sugar}}' if sug else '')+' in a snug saucepan'+(' with '+season if season else '')+'. Heat gently'+(', stirring until the sugar dissolves' if sug else '')+'. Add the pears in one layer, working in batches if needed.','Cover and simmer very gently, turning and basting carefully, until a small knife enters the flesh easily: '+('1–3 hours for hard winter pears, checking after 45 minutes' if winter else ('25–45 minutes for whole pears' if whole else '15–30 minutes for halves'))+'. Add a little water if the pan dries before the fruit softens.','Lift out the pears. Remove any whole spices or zest strips. Simmer the liquid uncovered for 5–10 minutes until lightly syrupy, then spoon it over the fruit.']
 steps+=['Cool briefly in a shallow container, then refrigerate within 2 hours. Chill for at least 1 hour before serving.'] if cold else ['Rest for 5 minutes and serve warm, or cool promptly and refrigerate.']
 return add(n,title,fruit,(240 if winter else 60)+(60 if cold else 0),desc,items,steps,notes)
